/*
 * A138694  Numbers n such that the set {2*n+p^2, p any prime} contains
 *          exactly one prime.
 * https://oeis.org/A138694
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n-th integer n ≡ 1 (mod 3) for which 2 n + 9 is
 *            prime. Equivalently, if p_k is the k‑th prime > 9 with p_k ≡ 2
 *            (mod 3), then a(k) = (p_k − 9)/2. This sequence is generated by
 *            enumerating primes p ≡ 2 mod 3 and mapping each to (p − 9)/2
 * Range:     u8 n <= 26, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   grow_seq, sieve_primes
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include "../utils/sieve_primes.h"
#include "../utils/grow_seq.h"

/* Prime limit chosen to generate at least 100 000 qualifying primes
   (roughly enough for n up to 10 000). */
#define PRIME_LIMIT 4000000ULL

static bool primes_initialized = false;
static idx_t  *prime_list   = NULL;
static size_t prime_cnt     = 0;

static void init_primes(void)
{
    if (!primes_initialized) {
        sieve_primes(PRIME_LIMIT, &prime_list, &prime_cnt);
        primes_initialized = true;
    }
}

seq_t a(idx_t n)
{
    /* Lazy generation of sequence terms */
    static seq_t *seq          = NULL;
    static size_t seq_len      = 0;
    static size_t seq_cap      = 0;
    static size_t prime_idx    = 0;

    init_primes();

    while (seq_len < n) {
        if (prime_idx >= prime_cnt) {
            /* Extremely unlikely for n <= 10 000 with PRIME_LIMIT.
               If required, extend limit (unnecessary for problem constraints). */
            return 0;
        }
        idx_t p = prime_list[prime_idx++];
        if (p > 9 && (p % 3) == 2) {
            seq_t val = ((seq_t)p - 9) / 2;
            grow_seq(&seq, &seq_cap, seq_len + 1);
            seq[seq_len++] = val;
        }
    }

    return seq[n - 1];
}
